INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)VALUES (  'media',  'media',  true,  10485760,  ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'video/mp4', 'application/pdf']::text[])ON CONFLICT (id) DO UPDATE SET  public = true,  file_size_limit = 10485760,  allowed_mime_types = ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'video/mp4', 'application/pdf']::text[];DROP POLICY IF EXISTS "media_select_public" ON storage.objects;CREATE POLICY "media_select_public"  ON storage.objects FOR SELECT  USING (bucket_id = 'media');DROP POLICY IF EXISTS "media_insert_authenticated" ON storage.objects;CREATE POLICY "media_insert_authenticated"  ON storage.objects FOR INSERT  WITH CHECK (    bucket_id = 'media'    AND auth.role() = 'authenticated'  );DROP POLICY IF EXISTS "media_delete_authenticated" ON storage.objects;CREATE POLICY "media_delete_authenticated"  ON storage.objects FOR DELETE  USING (    bucket_id = 'media'    AND auth.role() = 'authenticated'  );
